<?php declare(strict_types=1);require_once __DIR__.'/auth_check.php';require_once __DIR__.'/role_check.php';require_once __DIR__.'/db.php';$rows=$conn->query("SELECT m.*,COUNT(a.id) invited,SUM(CASE WHEN a.signed_at IS NOT NULL AND a.attendance_status IN('Present','Online','Late') THEN 1 ELSE 0 END) signed_present,c.chair_staff_id FROM committee_meetings m JOIN committees c ON c.id=m.committee_id LEFT JOIN committee_meeting_attendance a ON a.meeting_id=m.id WHERE c.committee_name='Consultancy Committee' GROUP BY m.id ORDER BY m.meeting_date DESC,m.id DESC")->fetchAll();$h=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Consultancy attendance</title><link rel="stylesheet" href="/assets/style.css"><style>main{max-width:1000px;margin:auto;padding:1rem}table{width:100%;border-collapse:collapse}th,td{border:1px solid #ccd3da;padding:.7rem}</style></head><body><?php require __DIR__.'/nav.php';?><main><h1>Consultancy Meeting Attendance</h1><p>Each member signs their own attendance. The committee head certifies the list after the required half-plus-one quorum signs.</p><table><thead><tr><th>Meeting</th><th>Invited</th><th>Required</th><th>Signed</th><th>Certification</th><th>Action</th></tr></thead><tbody><?php foreach($rows as$r):$required=(int)floor((int)$r['invited']/2)+1;?><tr><td><?=$h($r['meeting_date'].' — '.$r['meeting_title'])?></td><td><?=(int)$r['invited']?></td><td><?=$required?></td><td><?=(int)$r['signed_present']?></td><td><?=$r['attendance_approved_at']?'Approved '.$h($r['attendance_approved_at']):'Pending'?></td><td><a href="/consultancy_attendance_approval.php?meeting_id=<?=(int)$r['id']?>">Sign or approve</a></td></tr><?php endforeach;?></tbody></table></main></body></html>
